import React, { Component } from "react";
import "./Homepage.css";

export default class Homepage extends Component {
  constructor(props) {
    super(props);
    this.state = {
      currentIndex: 0,
      homepage: null,
    };
  }

  componentDidMount() {
    fetch(`http://localhost:3001/pages/5`, {
      method: 'POST',  // השארת שיטת POST
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({})  // שמירה על גוף הבקשה כ-JSON ריק
    })
    .then(response => response.json())
    .then(data => {
      this.setState({ homepage: data });
    })
    .catch(error => console.error('Error fetching data:', error));
  }

  goToPrevious = () => {
    const { currentIndex, homepage } = this.state;
    const isFirstSlide = currentIndex === 0;
    const newIndex = isFirstSlide ? homepage.gallery?.length - 1 : currentIndex - 1;
    this.setState({ currentIndex: newIndex });
  };

  goToNext = () => {
    const { currentIndex, homepage } = this.state;
    const isLastSlide = currentIndex === homepage.gallery?.length - 1;
    const newIndex = isLastSlide ? 0 : currentIndex + 1;
    this.setState({ currentIndex: newIndex });
  };

  render() {
    const { currentIndex, homepage } = this.state;
    if (!homepage) return null;  // הוספת החזרת null כשאין נתונים

    const homeGallery = homepage.gallery;
    const isSingleSlide = homeGallery?.length <= 1;

    return (
      <div className="gallery">
        {!isSingleSlide && (
          <button onClick={this.goToPrevious} className="arrow left-arrow">
            ❮
          </button>
        )}

        <div className="slider">
          <div className="slider-inner" style={{ transform: `translateX(-${currentIndex * 100}%)` }}>
            {homeGallery?.map((image, index) => (
              <div className="slide" key={index}>
                <div className="image" style={{ backgroundImage: `url(${image.url})` }}></div>
                <a href="./Service">
                  <button className="gallery-button">מצא את חיית המחמד שלי</button>
                </a>
              </div>
            ))}
          </div>
        </div>

        {!isSingleSlide && (
          <button onClick={this.goToNext} className="arrow right-arrow">
            ❯
          </button>
        )}

        <div className="squares-container">
          {homeGallery?.map((_, index) => (
            <div
              className={`square ${currentIndex === index ? 'active' : ''}`}
              key={index}
              onClick={() => this.setState({ currentIndex: index })}
            ></div>
          ))}
        </div>
      </div>
    );
  }
}
